        return newL < bandLo1e18 || newL > bandHi1e18;
    }

    event AdminTransferStarted(address indexed admin, address indexed pendingAdmin);
    event AdminTransferred(address indexed previousAdmin, address indexed newAdmin);

    /// @notice Nominate a new admin (two-step, mirroring Ownable2Step): the
    ///         role only moves when the nominee calls `acceptAdmin`.
    ///         Re-nominate to overwrite a pending offer; nominate address(0)
    ///         to cancel it.
    function transferAdmin(address newAdmin) external onlyAdmin {
        pendingAdmin = newAdmin;
        emit AdminTransferStarted(admin, newAdmin);
    }

    /// @notice Complete an admin rotation — callable only by the nominee,
    ///         proving the destination address can transact on this chain
    ///         before the old admin relinquishes anything.
    function acceptAdmin() external {
        if (msg.sender != pendingAdmin) revert NotPendingAdmin(msg.sender);
        emit AdminTransferred(admin, msg.sender);
        admin = msg.sender;
        pendingAdmin = address(0);
    }

    /// @notice Admin withdraws accrued fee-pool USDG to the admin. Bounties are
    ///         paid from the same pool; this drains the residual. v5.3.3: fees
    ///         are the ops role's revenue — its gate and destination.
    function withdrawFees(uint256 amount) external onlyAdmin {
        if (amount > feePoolUsdg) amount = feePoolUsdg;
        feePoolUsdg -= amount;
        usdg.safeTransfer(admin, amount);
        emit FeesWithdrawn(admin, amount);
    }

    /// @dev Reserved slots for future storage appended via upgrades. New
    ///      variables MUST be declared immediately before this gap, shrinking
    ///      it by the slots they consume — never reorder, retype, or remove
    ///      anything above. See src/upgradeable/RUNBOOK.md.
    uint256[50] private __gap;
}

